const SUPA_URL = $env.SUPABASE_URL;
const SUPA_KEY = $env.SUPABASE_KEY;

// Tablas base del sistema (no vistas, esas se recalculan solas de estas).
const TABLAS = ['productos', 'ventas', 'venta_items', 'socios', 'facturas_proveedor', 'mp_movimientos', 'configuracion_precios', 'config_cuotas_ml'];

const backup = { fecha: new Date().toISOString(), tablas: {} };
const resumen = [];

for (const tabla of TABLAS) {
  const resp = await this.helpers.httpRequest({
    method: 'GET',
    url: `${SUPA_URL}/rest/v1/${tabla}`,
    qs: { select: '*', limit: 20000 },
    headers: { apikey: SUPA_KEY, Authorization: 'Bearer ' + SUPA_KEY },
    json: true,
    returnFullResponse: true,
    ignoreHttpStatusErrors: true,
  });
  if (resp.statusCode >= 200 && resp.statusCode < 300) {
    backup.tablas[tabla] = resp.body;
    resumen.push({ tabla, filas: resp.body.length, resultado: 'OK' });
  } else {
    resumen.push({ tabla, filas: 0, resultado: `ERROR ${resp.statusCode}: ` + JSON.stringify(resp.body) });
  }
}

const hoy = new Date().toISOString().slice(0, 10); // YYYY-MM-DD
const nombreArchivo = `backup-${hoy}.json`;
const contenido = JSON.stringify(backup);

// Sube el snapshot al bucket privado "backups" de Supabase Storage.
// x-upsert:true permite reemplazar si se corre 2 veces el mismo dia.
const upload = await this.helpers.httpRequest({
  method: 'POST',
  url: `${SUPA_URL}/storage/v1/object/backups/${nombreArchivo}`,
  headers: {
    apikey: SUPA_KEY,
    Authorization: 'Bearer ' + SUPA_KEY,
    'Content-Type': 'application/json',
    'x-upsert': 'true',
  },
  body: contenido,
  returnFullResponse: true,
  ignoreHttpStatusErrors: true,
});

return [{ json: {
  archivo: nombreArchivo,
  tamano_bytes: contenido.length,
  resumen_tablas: resumen,
  upload_status: upload.statusCode,
  upload_ok: upload.statusCode >= 200 && upload.statusCode < 300,
  upload_resultado: upload.body,
} }];
